using System; using System.Collections.Generic; using UnityEngine; namespace MyLumo { [Serializable] public class OutfitState { public string hat,top,accessory,shoes; } public class LumoInventory:MonoBehaviour { [SerializeField] List<string> items=new(); public OutfitState outfit=new(); public IReadOnlyList<string> Items=>items; public bool Has(string id)=>!string.IsNullOrWhiteSpace(id)&&items.Contains(id); public void Add(string id){if(!string.IsNullOrWhiteSpace(id)&&!items.Contains(id))items.Add(id);} public void EquipHat(string id){Add(id);outfit.hat=id;} public void EquipTop(string id){Add(id);outfit.top=id;} public void EquipAccessory(string id){Add(id);outfit.accessory=id;} } }
